def is_palindrome(n):
    """
    Helper function to check if a number is a palindrome.
    """
    return str(n) == str(n)[::-1]

def even_odd_palindrome(n):
    count_even = 0
    count_odd = 0
    i = 1
    while i <= n:
        if is_palindrome(i):
            if i % 2 == 0:
                count_even += 1
            else:
                count_odd += 1
        i += 1
    return (count_even, count_odd)

if __name__ == "__main__":
    n = int(input("Enter a positive integer: "))
    even, odd = even_odd_palindrome(n)
    print(f"Number of even palindromes: {even}")
    print(f"Number of odd palindromes: {odd}")
```

This script includes the `is_palindrome` helper function to check if a number is a palindrome, and the main `even_odd_palindrome` function that uses this helper function to count the even and odd integer palindromes within the given range. The script also includes some basic input handling for testing purposes.
